class DiscountStrategy:
    FIDELITY_DISCOUNT_RATE = 0.05
    BULK_ITEM_QUANTITY_THRESHOLD = 20
    BULK_ITEM_DISCOUNT_RATE = 0.1
    LARGE_ORDER_DISCOUNT_RATE = 0.07
    LARGE_ORDER_MIN_PRODUCTS = 10

    def __init__(self, customer, cart, promotion=None):
        self._customer = customer
        self._cart = cart
        self._promotion = promotion
        self._total = self._compute_total()

    @property
    def customer(self):
        return self._customer

    @customer.setter
    def customer(self, value):
        self._customer = value

    @property
    def cart(self):
        return self._cart

    @cart.setter
    def cart(self, value):
        self._cart = value

    @property
    def promotion(self):
        return self._promotion

    @promotion.setter
    def promotion(self, value):
        self._promotion = value

    def total(self):
        self._total = self._compute_total()
        return self._total

    def due(self):
        discount = self._compute_discount()
        return self._total - discount

    def _compute_total(self):
        return sum(item['quantity'] * item['price'] for item in self.cart)

    def _compute_discount(self):
        if self._promotion is None:
            return 0
        return self._promotion(self)

    @staticmethod
    def FidelityPromo(order):
        if order.customer['fidelity'] >= DiscountStrategy.FIDELITY_DISCOUNT_RATE_THRESHOLD if hasattr(DiscountStrategy, 'FIDELITY_DISCOUNT_RATE_THRESHOLD') else order.customer['fidelity'] >= 1000:
            return order.total() * DiscountStrategy.FIDELITY_DISCOUNT_RATE
        return 0

    @staticmethod
    def BulkItemPromo(order):
        return sum(
            item['quantity'] * item['price'] * DiscountStrategy.BULK_ITEM_DISCOUNT_RATE
            for item in order.cart
            if item['quantity'] >= DiscountStrategy.BULK_ITEM_QUANTITY_THRESHOLD
        )

    @staticmethod
    def LargeOrderPromo(order):
        distinct_products = {item['product'] for item in order.cart}
        if len(distinct_products) >= DiscountStrategy.LARGE_ORDER_MIN_PRODUCTS:
            return order.total() * DiscountStrategy.LARGE_ORDER_DISCOUNT_RATE
        return 0
